local _, ZoneLore = ...

ZoneLore.Zones = {
	[947] = {
		name = "Azeroth",
		short = "Azeroth is the name of the world in which the majority of the Warcraft series is set. At its core dwells a slumbering worldsoul, the nascent spirit of a titan.",
		full = "Azeroth is the name of the world in which the majority of the Warcraft series is set. At its core dwells a slumbering worldsoul, the nascent spirit of a titan. Floating within the infinite reaches of the Great Dark Beyond, Azeroth once fell to the corruption of the Old Gods and their Black Empire, until the Pantheon of Order defeated them and began the Ordering of the planet. It has since been populated by a multitude of different races and creatures, some native to the planet, others from different worlds; all carving out territories for themselves. However, Azeroth also became the target of enemies from beyond, including the chaotic armies of the Burning Legion and the voracious forces of the Void. Those responsible for the world's safety are not a united group; Azeroth's history is filled with wars and conflicts, and in modern times, the Alliance and the Horde are the major political factions of the mortal races. Each represents the unification of various racial, cultural, and philosophical civilizations. Despite their incessant conflicts and bloodshed, both factions treasured Azeroth, believing it should be cared for and protected, and in times of grave danger, they are willing to work together in the face of a common foe.\n\nAlthough unnamed and numerous, it is thanks to the brave adventurers that Azeroth, and the universe itself, have been saved on numerous occasions. There are also many organizations dedicated to the protection of the world, which maintain an independent position during global conflicts, such as the Cenarion Circle, Earthen Ring, Kirin Tor, Argent Crusade, and Kingdom of dragons among many others.",
		source = "https://warcraft.wiki.gg/wiki/Azeroth",
	},
	[1411] = {
		name = "Durotar",
		short = "Durotar, the land named after Thrall's father, Durotan, lies on the eastern coast of Kalimdor. It borders the Northern Barrens to the west and the coastal lands of Azshara to the north.",
		full = "Durotar, the land named after Thrall's father, Durotan, lies on the eastern coast of Kalimdor. It borders the Northern Barrens to the west and the coastal lands of Azshara to the north. The land is rocky, and the soil is cracked and red, not unlike the orcs' homeland of Draenor. It has many crags and canyons, where dangerous creatures take residence. It is a harsh land to survive in, very dry and hot, and the vegetation is sparse. The orcs, however, see a harsh beauty in the land. Durotar is a proving ground for young orcs, who are sent to the Valley of Trials to complete several rites of passage before they are considered fit for the challenges that lie ahead. Since the orcs founded Orgrimmar, Durotar has become something of a home for all of the Horde races, especially the Darkspear jungle trolls, who are mainly settled on the Echo Isles.",
		source = "https://warcraft.wiki.gg/wiki/Durotar",
	},
	[1412] = {
		name = "Mulgore",
		short = "The green, verdant plains of Mulgore are home to the noble tauren. Mulgore is nestled in the foothills of the Stonetalon Mountains to the north, and protected by a natural wall of mountains on all sides.",
		full = "The green, verdant plains of Mulgore are home to the noble tauren. Mulgore is nestled in the foothills of the Stonetalon Mountains to the north, and protected by a natural wall of mountains on all sides. The only pass through these mountains is currently closed off by the Great Gate, which leads into the Southern Barrens to the east.\n\nMulgore provides bounty for the hunt, as a diversity of wild beasts roam the rolling plains and climb the foothills of the surrounding range. In the northern section of Mulgore, the new Camp Sungraze sits in the shadows of the mesas of Thunder Bluff, a tauren city which towers above the plains. Bloodhoof Village is centrally located and surrounded by the clear waters of Stonebull Lake, while further south on Red Cloud Mesa, Camp Narache stands as the principal training camp for all young tauren.\n\nDespite the serene landscape and the pine-scented breeze, Mulgore is fraught with trouble. Brambleblade Ravine and the sacred Red Rocks are overrun by quilboars, and they continue to spread into the rest of Red Cloud Mesa. The goblin-run Venture Company infests the Venture Co. Mine in the eastern mountain face, while the Grimtotem tribe try to take vengeance against the other tauren by poisoning their water wells. The Windfury harpy tribe lay claim to the extreme northern reaches of Mulgore and the southeast mountain face. A tribe of gnolls known as the Palemane make their home at the cave called Palemane Rock, as well in scattered camps along the southern mountains.",
		source = "https://warcraft.wiki.gg/wiki/Mulgore",
	},
	[1413] = {
		name = "The Barrens",
		short = "The Barrens is a large zone in central Kalimdor controlled mostly by the Horde.",
		full = "The Barrens is a large zone in central Kalimdor controlled mostly by the Horde. It is a massive savanna, with low mountains serving as natural borders and with a few oases in the north-central region around the Crossroads. These oases, sourcing from the Wailing Caverns, are known for the life energy flowing from their waters, invigorating the plants and beasts that drink it.\n\nLong ago, the Barrens was mostly forests, tended to by the night elves. The combination of the Burning Legion, war, and the Great Sundering turned the woodland into a barren expanse. Now, the divided Barrens are a shade of their glory, one that is in short supply in this dry place. Despite this, it is more than an infertile soil and sand.",
		source = "https://warcraft.wiki.gg/wiki/Barrens",
	},
	[1414] = {
		name = "Kalimdor",
		short = "Kalimdor [ˈkælɪmdɔɹ] (Titan and Darnassian for land of eternal starlight) is one of the main continents of Azeroth. The continent lie to the west of the Great Sea and to the east of the Forbidding Sea.",
		full = "Kalimdor [ˈkælɪmdɔɹ] (Titan and Darnassian for land of eternal starlight) is one of the main continents of Azeroth. The continent lie to the west of the Great Sea and to the east of the Forbidding Sea. Kalimdor can be further divided into three regions known as Northern Kalimdor, Central Kalimdor, and Southern Kalimdor. It is home to the night elves, orcs, tauren, trolls, and draenei. Other races present include the ogres, centaur, naga, demons, and other, more minor races.\n\nKalimdor was primarily the domain of the night elves in the ten thousand years between the War of the Ancients and the Battle of Mount Hyjal. In the years since the Third War, night elf dominion has given way as the tauren adopted a more centralized system and accepted their allies, the orcs and the trolls of the Horde into their midst. The recent arrival of the draenei also adds a new power to the map. The continent is now a politically divided one, the Horde have established strong control in the central and eastern areas while the night elves, now aided by the draenei, preserve footholds in northwestern areas.",
		source = "https://warcraft.wiki.gg/wiki/Kalimdor",
	},
	[1415] = {
		name = "Eastern Kingdoms",
		short = "The Eastern Kingdoms (occasionally called Azeroth or the Old World) is one of the main continents of Azeroth. The continent lie to the east of the Great Sea and to the west of the Forbidding Sea.",
		full = "The Eastern Kingdoms (occasionally called Azeroth or the Old World) is one of the main continents of Azeroth. The continent lie to the east of the Great Sea and to the west of the Forbidding Sea. They are made up of a group of smaller continents (Azeroth, Khaz Modan and Lordaeron) formed from the original continent of Kalimdor following the Great Sundering. The central part of the Eastern Kingdoms is dominated by the mountains of Khaz Modan and the Redridge Mountains. It is home to the dwarves, gnomes, high and blood elves, humans, worgen, and the Forsaken. Other races present include the orcs, goblins, draenei, naga, ogres and other, more minor races.",
		source = "https://warcraft.wiki.gg/wiki/Eastern_Kingdoms",
	},
	[1416] = {
		name = "Alterac Mountains",
		short = "The Alterac Mountains (or Mountains of Alterac) are a range of towering, snow-capped mountains in central Lordaeron. Formerly a standalone zone, it is now considered part of the Hillsbrad Foothills.",
		full = "The Alterac Mountains (or Mountains of Alterac) are a range of towering, snow-capped mountains in central Lordaeron. Formerly a standalone zone, it is now considered part of the Hillsbrad Foothills. The mountains were home to the former human nation of Alterac and included the settlements of Alterac City and Strahnbrad, whose ruins are now occupied by either Crushridge ogres or the Syndicate.",
		source = "https://warcraft.wiki.gg/wiki/Alterac_Mountains",
	},
	[1417] = {
		name = "Arathi Highlands",
		short = "The Arathi Highlands (sometimes referred to as simply Arathi, the Highlands, or Arathor) are a region in southeastern Lordaeron, east of Hillsbrad Foothills and south of the Hinterlands.",
		full = "The Arathi Highlands (sometimes referred to as simply Arathi, the Highlands, or Arathor) are a region in southeastern Lordaeron, east of Hillsbrad Foothills and south of the Hinterlands. To the south lies the Thandol Span, a massive dwarven construction that bridges the canal between Lordaeron and Khaz Modan, connecting the Highlands with the Wetlands. It is a land rich in history, having once been the home of the first human empire of Arathor, who gave the region its name, and later the Kingdom of Stromgarde. The Highlands are sometimes inaccurately described as the birthplace of humanity.\n\nFollowing the death of King Thoras Trollbane, the once-mighty Stromgarde fell on hard times after the Third War. Under the lead of Prince Galen Trollbane, the kingdom was unable to resist the might of its many foes. The city of Stromgarde, located in the southwest, was assailed by a combined force of Syndicate, vengeful Alteraci who sought to lay low the kingdom, the native Witherbark tribe of forest trolls that dot the forest to the east, and the Boulderfist ogres, whose hovels dot the east and central regions of the area. The main hubs of activity became Refuge Pointe for the Alliance and Hammerfall for the Horde.\n\nFor years, Prince Trollbane led the human defenders, holding but a single section of the city, until he was slain by Horde agents seeking Trol'kalar, later being resurrected to undeath by the Forsaken. In the end, he betrayed his new allies to reclaim Stromgarde Keep, but was ultimately killed when he tried to deceive the death knights of the Ebon Blade, during which it was revealed the prince had murdered his own father, thus robbing the kingdom of its mighty leader. The battle ultimately ended in the Alliance's favor, with Stromgarde victorious, leaving King Danath Trollbane as the new leader of the kingdom.",
		source = "https://warcraft.wiki.gg/wiki/Arathi_Highlands",
	},
	[1418] = {
		name = "Badlands",
		short = "The Badlands is an arid and desolate region in Khaz Modan accessed via the Searing Gorge to the west and Loch Modan to the north.",
		full = "The Badlands is an arid and desolate region in Khaz Modan accessed via the Searing Gorge to the west and Loch Modan to the north. Only the hardiest of creatures can survive in the arid wastes, such as coyotes, cougars, and buzzards. The black dragonflight have a pronounced presence in the Lethlor Ravine and Dustbowl. Scattered across the Badlands are also camps of the Dustbelcher ogres.\n\nThe region is often mistaken for being an Alliance territory. It is an extreme environment, it is imperative to have an excellent map of the ruins and surroundings to survive, the sandstorms sweeping the region can confuse the landmarks. It is advisable to travel at night, to sleep during the day, to protect your face from sand and winds, and to provide plenty of water, or a mage.\n\nDespite its position between Stormwind and Dun Morogh, the Badlands have traditionally been Horde territory, though the Alliance have recently established Dragon's Mouth in the western part of the region. In the east is the goblin town of Fuselight and its sister port town, Fuselight-by-the-Sea, both controlled by the neutral Steamwheedle Cartel.\n\nIn the northeast, near the border with Loch Modan, lie the ruins of a titan-forged fortress known as Uldaman, home to titan-forged earthen, savage troggs, and much information about the origins of the dwarven race, while the smaller Tomb of the Watchers has recently been unearthed in the center of the region. As a result, the Alliance-affiliated Explorers' League, the dwarven Dark Iron clan, and the blood elven Reliquary are fighting for control over the ruins and any titan artifacts that may lie within.",
		source = "https://warcraft.wiki.gg/wiki/Badlands",
	},
	[1419] = {
		name = "Blasted Lands",
		short = "The Blasted Lands are desolate and barren lands located in the southern part of the Eastern Kingdoms, south of the Swamp of Sorrows and east of Deadwind Pass.",
		full = "The Blasted Lands are desolate and barren lands located in the southern part of the Eastern Kingdoms, south of the Swamp of Sorrows and east of Deadwind Pass. Once part of the Black Morass, the swamps were twisted and dried up by the demonic magic that brought the Dark Portal into being, spewing the rampaging orcish Horde into Azeroth. Though the original portal was destroyed by Khadgar in the Second War, it was later rebuilt by the Ner'zhul's Horde, leading to the events of the invasion of Draenor and the destruction of the orcs' homeworld.\n\nWhen the Iron Horde began its invasion, the gateway led to the alternate Draenor.",
		source = "https://warcraft.wiki.gg/wiki/Blasted_Lands",
	},
	[1420] = {
		name = "Tirisfal Glades",
		short = "Tirisfal Glades, also known as the Tirisfal Glade or simply Tirisfal, is an eerie region found on the northern coast of Lordaeron.",
		full = "Tirisfal Glades, also known as the Tirisfal Glade or simply Tirisfal, is an eerie region found on the northern coast of Lordaeron. It was named after the Titan Keeper Tyr, as Tirisfal means \"Tyr's Fall\" in the vrykul tongue. Before receiving this name, the region was simply called the Eastern Glades. The lands of the Forsaken, the wooded hills are seeped through with the curse of the Lich King's plague. The sky over Tirisfal is eternally gloomy and tinted a blighted green, and the trees and other flora desperately cling to their last shreds of life.\n\nThose who inhabit the area of Tirisfal used to feel two conflicting energies emanating from the earth: the remaining spiritual essence of Keeper Tyr, and that of his enemy Zakajz. Some tapped into Tyr's energy; others would become attuned with the C'Thrax's dark aura. Although tainted and melancholy, Tirisfal still very much has its own unique, haunting beauty, particularly in such areas as the stony North Coast, the town of Brill, and the deep atmosphere of the ruined Agamand Mills.\n\nTirisfal Glades is home not only to the Forsaken but to their enemies as well. The Scarlet Crusade has several outposts here, including the seat of their religious faith, the Scarlet Monastery. The minions of the Scourge are also ever-present, tainting the derelict farmsteads and dilapidated mills with their foul presence.\n\nIn the aftermath of the Battle for Lordaeron, Tirisfal Glades became a contested territory between the Alliance and the Horde, with the ruins of Capital City becoming heavily plagued and the central areas of Tirisfal itself being overrun with Blighted Soldiers risen by Sylvanas Windrunner, who attack anyone on sight.",
		source = "https://warcraft.wiki.gg/wiki/Tirisfal_Glades",
	},
	[1421] = {
		name = "Silverpine Forest",
		short = "Silverpine Forest, or simply Silverpine, is a vast, ancient forest that runs along Lordaeron's rugged western coast. The land ranges from fairly flat to hilly, and is nestled among even taller mountains.",
		full = "Silverpine Forest, or simply Silverpine, is a vast, ancient forest that runs along Lordaeron's rugged western coast. The land ranges from fairly flat to hilly, and is nestled among even taller mountains. Gilneas borders the forest to the south, the Hillsbrad Foothills to the southeast, while Tirisfal Glades lays to the north. Lordamere Lake serves as Silverpine's eastern border. The woodland is haunted and wild, characterized by its tall, silver-barked pines towering over grassy knolls. The forest is eerily silent, with dilapidated farmsteads and abandoned mines to dot the land, home now to the darker denizens of the woods.\n\nThe Forsaken control the northern forest and that region serves as the staging area for their armies that march into the besieged kingdom of Gilneas. What remains of the human population retains control of the southern forest, but they are desperate and their forces thinly stretched. Since the fall of the Greymane Wall and the spread of the worgen curse, the Gilneas Liberation Front has decided to strike back at the Forsaken after their first invasion, openly fighting against their oppressors.\n\nThough the territory belongs to the Forsaken, their claim was disputed by the wizards of Dalaran, Gilneans and the raised Gilnean noblemen that now have entrenched themselves along with the Scourge remnants in the Baron Silverlaine's former fortress, the Shadowfang Keep.\n\nAfter the Battle for Lordaeron, the region became a prime target for the Alliance, claiming some parts of the forest as well as attacking Forsaken outposts throughout the region, with the Bloodfang pack taking command of Fenris Isle. At some point after this, the Bloodfang pack claimed Shadowfang Keep, retaining control of it by the end of the war.",
		source = "https://warcraft.wiki.gg/wiki/Silverpine_Forest",
	},
	[1422] = {
		name = "Western Plaguelands",
		short = "The Western Plaguelands are located in northern Lordaeron, wedged between Tirisfal Glades to the west, the Eastern Plaguelands to the east, and the Alterac Mountains to the south.",
		full = "The Western Plaguelands are located in northern Lordaeron, wedged between Tirisfal Glades to the west, the Eastern Plaguelands to the east, and the Alterac Mountains to the south. It is a reclaimed portion of the tainted lands of the former Kingdom of Lordaeron, predominately held by the Argent Crusade, though the land is still haunted by the remnants of the undead Scourge.\n\nDespite being where the Plague took hold in Lordaeron, the Western Plaguelands were in surprisingly better condition, though still quite dead, than the Eastern Plaguelands.\n\nThe largest Scourge-controlled area left here is Caer Darrow, beneath which is an underground complex housing the undead's Scholomance. The Argent Crusade is based in their leader's home town, Hearthglen, which was reclaimed from the hands of now fallen Scarlet Crusade. One of the most notable places in this region is Uther's Tomb.",
		source = "https://warcraft.wiki.gg/wiki/Western_Plaguelands",
	},
	[1423] = {
		name = "Eastern Plaguelands",
		short = "The Eastern Plaguelands is the more heavily devastated half of the Plaguelands, a region that was once known as the Eastweald and was part of the Kingdom of Lordaeron.",
		full = "The Eastern Plaguelands is the more heavily devastated half of the Plaguelands, a region that was once known as the Eastweald and was part of the Kingdom of Lordaeron. For years the area has suffered from heavy Scourge corruption. The ground is brown and dead, infected animals run rampant, giant mushrooms litter the landscape, and an orange mist pollutes the air. The Plaguewood is the most infested part of the zone.\n\nThe city of Stratholme, located on the Eastern Plaguelands' northern edge, played an important role for the Scourge during the Third War: It was there that Prince Arthas of Lordaeron enacted the Culling of Stratholme, marking a point of no return in his fall to darkness. After the war, the Eastern Plaguelands was a center of Scourge power in Lordaeron, with Stratholme acting as their southern capital under the rule of the lich Kel'Thuzad.\n\nOver time, the Scourge's grasp on the Eastern Plaguelands has waned. The Argent Crusade, based out of Light's Hope Chapel in the east of the zone, built a series of towers to be \"points of light\" in the Plaguelands' darkness and to help them combat the undead. The Scourge also lost much of its influence in the neighboring Western Plaguelands, which the Cenarion Circle worked to heal. Multiple attempts have been made to clear the undead from Stratholme, and after the Silver Hand swept through the city during the third invasion of the Burning Legion, they resolved to keep a more watchful eye on it. The Argent towers and other areas are oases for those who traverse the Eastern Plaguelands.\n\nOther notable locations include Tyr's Hand, which was part of the Scarlet Enclave held by the Scarlet Crusade before the war against the Lich King; Zul'Mashar, which was once the capital of the Mossflayer forest trolls but has since become a shadow of its former glory; and the Marris Stead, the former home of Nathanos Blightcaller.",
		source = "https://warcraft.wiki.gg/wiki/Eastern_Plaguelands",
	},
	[1424] = {
		name = "Hillsbrad Foothills",
		short = "The Hillsbrad Foothills (or Hillsbrad Plains) is a large region of the former kingdom of Lordaeron and is mostly untouched by the Scourge.",
		full = "The Hillsbrad Foothills (or Hillsbrad Plains) is a large region of the former kingdom of Lordaeron and is mostly untouched by the Scourge. It was here that the first battle took place between the forces of the Alliance of Lordaeron and the Orcish Horde during the Second War. Decades later, this beautiful land is torn by conflict and aggressive expansion of the Forsaken, trying to conquer the whole of Lordaeron for themselves, opposed by dwarves of the Stormpike clan allied with Bloodfang worgen of the Alliance. The Forsaken maintain their holdings in Tarren Mill, which is the largest settlement in this region, and the dreaded Sludge Fields, where many terrifying experiments are being performed. As a result of their expansion, the humans of Southshore were driven off to Fenris Keep in Silverpine Forest, and the town itself was devastated with the New Plague. The land also consists of Alterac Mountains and its surroundings, such as Dalaran Crater and Strahnbrad.\n\nThe Stormpike clan attempted a large counterattack from the Alterac Mountains to the north, but their plans were thwarted by Horde heroes and they lost many of their forces. Despite this, by the time of the third invasion of the Burning Legion, the Stormpikes still maintained presence.",
		source = "https://warcraft.wiki.gg/wiki/Hillsbrad_Foothills",
	},
	[1425] = {
		name = "The Hinterlands",
		short = "The Hinterlands are a wooded and mountainous region located in the eastern part of Lordaeron, north of the Eastern Kingdoms.",
		full = "The Hinterlands are a wooded and mountainous region located in the eastern part of Lordaeron, north of the Eastern Kingdoms. Notable for the Wildhammer dwarves who made their residence at Aerie Peak in the west, it is here that these dwarves find and tame their world-renowned gryphons. The Hinterlands are also home to a large population of forest trolls, which are divided into three separate tribes, including the Revantusk tribe, who pledged their allegiance to the Horde. In the northern part of the region is the ancient, massive tree Seradane, where the agents of the green dragonflight have once been corrupted by the Emerald Nightmare. A massive portal on the side of the tree connects the servants of nature to her own realm, the Emerald Dream. The Hinterlands are also home to the Highvale high elves of Quel'Danil Lodge.",
		source = "https://warcraft.wiki.gg/wiki/Hinterlands",
	},
	[1426] = {
		name = "Dun Morogh",
		short = "Dun Morogh also called the Dun Morogh Peaks, is a snowy, forested mountain range in western Khaz Modan.",
		full = "Dun Morogh also called the Dun Morogh Peaks, is a snowy, forested mountain range in western Khaz Modan. It is the homeland of the dwarves and gnomes and contains the two races' respective capital cities of Ironforge (built into Ironforge Mountain) and Gnomeregan (built into the foothills of Chill Breeze Valley). The mountains of Dun Morogh are the highest in the Eastern Kingdoms -- its snowpack glaciers feed the rivers that create the verdant fields across the rest of Khaz Modan and its jagged peaks provide the dwarves with a limitless supply of ore. The region sits between the Searing Gorge to the south, Loch Modan to the east, and the Wetlands to the north. Mountains surround Dun Morogh on all sides, making it accessible only by certain passes that are currently watched over by dwarven troops.",
		source = "https://warcraft.wiki.gg/wiki/Dun_Morogh",
	},
	[1427] = {
		name = "Searing Gorge",
		short = "The Searing Gorge is a contested region in southern Khaz Modan. It is home to a group of exceptionally stout Dark Iron dwarves called the Thorium Brotherhood, who have split from the Dark Iron clan.",
		full = "The Searing Gorge is a contested region in southern Khaz Modan. It is home to a group of exceptionally stout Dark Iron dwarves called the Thorium Brotherhood, who have split from the Dark Iron clan.",
		source = "https://warcraft.wiki.gg/wiki/Searing_Gorge",
	},
	[1428] = {
		name = "Burning Steppes",
		short = "The Burning Steppes are located north of the Redridge Mountains and south of the Searing Gorge.",
		full = "The Burning Steppes are located north of the Redridge Mountains and south of the Searing Gorge. As such, they hold the only accessible land passage from the kingdom of Stormwind in the south to Khaz Modan and Lordaeron in the north. Now virtually abandoned by Stormwind's protection, the Burning Steppes is controlled by the orcish Blackrock clan, minions of the black dragonflight, and agents of Firelord Ragnaros. With the constant volcanic activity and flows of lava, the weather is perpetually hot and dry, and the land is absent of widespread vegetation.\n\nThe Blackrock orcs have long maintained a lasting settlement around the volcano known as Blackrock Stronghold, staying hidden from the road and always keeping watch for Alliance attacks. These orcs are more typical of the type of the First and Second wars rather than the current Horde in Kalimdor: Bloodthirsty and savage, they mine the mountains around Blackrock Spire for metals for their weapons and armor. At this time, they had allied with the Firegut ogres on the southern end of the steppes as well as the black dragonflight in preparation for a violent territorial expansion into lands protected by Stormwind. But the Alliance - not to mention their new Dark Iron dwarf allies - and certain members of the Horde did not allow them to succeed, and since then, the Blackrock Clan has been granted amnesty and a place in the New Horde under the leadership of Eitrigg.\n\nWhat awaits the Burning Steppes, now contested between Alliance and Horde during their first era of armistice and tentative trust, remains to be seen.",
		source = "https://warcraft.wiki.gg/wiki/Burning_Steppes",
	},
	[1429] = {
		name = "Elwynn Forest",
		short = "Elwynn Forest, the Forest of Elwynn or simply Elwynn, is a vast woodland of stately hardwoods nestled in the continent of Azeroth, just below the foothills of the Burning Steppes to the north.",
		full = "Elwynn Forest, the Forest of Elwynn or simply Elwynn, is a vast woodland of stately hardwoods nestled in the continent of Azeroth, just below the foothills of the Burning Steppes to the north. The Redridge Mountains lie to the east, and Duskwood lies to the south across the Nazferiti river. It is the heartland of the human Kingdom of kingdom of Stormwind and consequently is the starting point of all human adventurers.\n\nMarshal Dughan serves as the municipal law enforcer for Goldshire and Marshal McBride serves as the municipal law enforcer for Northshire Valley. Though much of the forest was burned down during the First War, trees and lush glades have grown anew. Stormwind City lies northwest of the forest and is heavily patrolled by the Stormwind guards.",
		source = "https://warcraft.wiki.gg/wiki/Elwynn_Forest",
	},
	[1430] = {
		name = "Deadwind Pass",
		short = "Deadwind Pass is a contested region located in central Azeroth, joining the southeastern reaches of the kingdom of Stormwind through Duskwood.",
		full = "Deadwind Pass is a contested region located in central Azeroth, joining the southeastern reaches of the kingdom of Stormwind through Duskwood. It is situated west of the Swamp of Sorrows, north of the Blasted Lands, and south of Redridge Mountains. It was, a score of years ago, considered a part of the Redridge Mountains. A foul wind constantly blows across the decimated canyon, giving it its name.\n\nDeadwind Pass is a stretch of land devoid of life, where the trees are reduced to withered husks, the marshes are a desiccated waste, and the sky turned a sepulchral gray with the sun covered in a burial shroud. At its center stands the imposing and enigmatic tower known as Karazhan, once the residence of the last Guardian of Tirisfal, Medivh, the tower lies abandoned and cloaked in dark enchantments since the death of its master. Deadwind Pass is now home to various haunting creatures, demons, malevolent spirits, and filthy beasts, that infest the region due to the curse left by Medivh upon his death.",
		source = "https://warcraft.wiki.gg/wiki/Deadwind_Pass",
	},
	[1431] = {
		name = "Duskwood",
		short = "Duskwood, originally called Brightwood, is a fiefdom of the kingdom of Stormwind located in the southern-central part of Azeroth, south of Elwynn Forest, east of Westfall, west of Deadwind Pass, and north of Stranglethorn Vale.",
		full = "Duskwood, originally called Brightwood, is a fiefdom of the kingdom of Stormwind located in the southern-central part of Azeroth, south of Elwynn Forest, east of Westfall, west of Deadwind Pass, and north of Stranglethorn Vale. Beneath the everlasting night, which gave Duskwood its current name, the fel magic unleashed by Medivh upon his death has transformed what was once a beautiful part of Elwynn Forest into a land covered in gnarled trees, along with the black fog hanging over the woods.\n\nDuskwood is inhabited by a defiant people who still cling to their holdings in the face of overwhelming adversity. On all sides lurk dangerous creatures, from hideous undead to ferocious Nightbane worgen and overgrown spiders. Ogres moving in have brought up even more problems. To fight against all these threats, the militia of Duskwood, known as the Night Watch, patrolled the main thoroughfare and protected Darkshire, wary of anything moving through the shadows.\n\nThe most prominent geographical feature of the region is the Twilight Grove, which contains one of the Great Trees with a portal leading into the Emerald Dream. The woods also feature several abandoned farmsteads, as well as the prominent Raven Hill Cemetery, which holds the graves of many who have known tragic fates and the restless bodies of others, stirred to undeath by necromancy.",
		source = "https://warcraft.wiki.gg/wiki/Duskwood",
	},
	[1432] = {
		name = "Loch Modan",
		short = "Loch Modan is a large area east of Dun Morogh, situated in eastern Khaz Modan. The gray and rugged mountains rise up on all sides around the loch, and the hills are lightly wooded with pine and birch.",
		full = "Loch Modan is a large area east of Dun Morogh, situated in eastern Khaz Modan. The gray and rugged mountains rise up on all sides around the loch, and the hills are lightly wooded with pine and birch. The loch was held in place by the now broken Stonewrought Dam, an architectural wonder of no equal on Azeroth.\n\nLoch Modan is heavily populated by hostile troggs, unearthed from caves below ground by the dwarven digs. They have since settled in the surrounding mountainous area and built crude camps and caves from which to strike at passing travelers. Other dangers include dangerous wildlife, aggressive kobolds, and the powerful ogres of the Mo'grosh Stronghold.",
		source = "https://warcraft.wiki.gg/wiki/Loch_Modan",
	},
	[1433] = {
		name = "Redridge Mountains",
		short = "The Redridge Mountains (also known as the Red Ridge Mountains, the Redridge Range, or simply Redridge) are located east of Elwynn Forest, northeast of Duskwood, and south of the Burning Steppes.",
		full = "The Redridge Mountains (also known as the Red Ridge Mountains, the Redridge Range, or simply Redridge) are located east of Elwynn Forest, northeast of Duskwood, and south of the Burning Steppes. Although it may be considered contested, Horde characters have no settlements or NPCs, and it is thus a place they use mostly for passing through to reach Flame Crest or Stonard.\n\nAn idyllic region of rushing rivers, towering elms, and rising elevations, the Redridge Mountains are under the protection of the kingdom of Stormwind. On the western bank of Lake Everstill is the Alliance town of Lakeshire, the central hub for this faction's adventurers, offering many services and quests, as well as flight paths. The crossroads known as the Three Corners, located in the southwest corner of the zone, connects the town of Lakeshire with Elwynn, Duskwood and, via the Lakeridge Highway, Stonewatch Keep. The highway itself is quite a dangerous place occupied by gnolls, murlocs, and wild animals.\n\nA force of Blackrock orcs from the Burning Steppes has once secured Stonewatch Keep for the Dark Horde, but are still in control of the northern roads. There are also a few camps located in Redridge -- an orc camp in Render's Valley, Shadowhide gnoll camps near the Tower of Ilgalar, and murloc camps near the lake. While the lake's surface appears peaceful enough, murlocs reside beneath the waves, and rumors of sightings of a sea monster persist. There are also raptor nests in the Mountains. In comparison with Westfall, Redridge is still relatively stable.",
		source = "https://warcraft.wiki.gg/wiki/Redridge_Mountains",
	},
	[1434] = {
		name = "Stranglethorn Vale",
		short = "Stranglethorn Vale (also called Stranglethorn Valley or simply Stranglethorn), sometimes spelled Stranglethorne, is a vast jungle at the southern tip of the Eastern Kingdoms, south of Duskwood.",
		full = "Stranglethorn Vale (also called Stranglethorn Valley or simply Stranglethorn), sometimes spelled Stranglethorne, is a vast jungle at the southern tip of the Eastern Kingdoms, south of Duskwood.\n\nStranglethorn is noteworthy for three things: its dangerous jungles, which require preparations of antidotes against its deadly wildlife and diseases such as Stranglethorn Fever; its jungle trolls, as Stranglethorn was once the center of the mighty Gurubashi Empire; and its pirates, primarily the Blackwater Raiders of Booty Bay and their archenemies the Bloodsail Buccaneers.",
		source = "https://warcraft.wiki.gg/wiki/Stranglethorn_Vale",
	},
	[1435] = {
		name = "Swamp of Sorrows",
		short = "The Swamp of Sorrows (also once known as the Swamps of Sorrow) is a contested territory in the southern part of the Eastern Kingdoms.",
		full = "The Swamp of Sorrows (also once known as the Swamps of Sorrow) is a contested territory in the southern part of the Eastern Kingdoms. Among its murk-ridden marshes stand settlements built by the orcs, humans, and goblins, as well as the ancient troll temple of Atal'Hakkar. It was once the northern part of an enormous swampland called the Black Morass.",
		source = "https://warcraft.wiki.gg/wiki/Swamp_of_Sorrows",
	},
	[1436] = {
		name = "Westfall",
		short = "Westfall is a fiefdom of the Kingdom of Stormwind, and was once its breadbasket.",
		full = "Westfall is a fiefdom of the Kingdom of Stormwind, and was once its breadbasket. Ravaged by the Old Horde during the Second War, these rich lands of rolling pastures and farms were once beautiful and green, until they were afflicted by drought and the mistreatment inflicted by the Defias Brotherhood, an organization of former stonemasons who became bandits under the command of Edwin VanCleef. The grass is yellowed, the fields are infested with ravenous carrion birds and mechanical harvest watchers who have gone rogue, while years of neglect and conflict have not improved the situation.\n\nAfter years of corruption and internal political conflicts caused by the black dragon Onyxia, Stormwind has been working hard to secure and renovate the region. The Westfall Brigade under the leadership of Marshal Gryan Stoutmantle, formerly known as the People's Militia, erected a bastion of military power in the region at Sentinel Hill from where they issue commands to anyone willing to aid the cause, and thus succeeded in defeating the Defias Brotherhood. Although most of the area's farms have fallen to disrepair, there are still farmers who bravely cling to their holdings.\n\nNow inhabited by transients, homeless citizens, and drifters, the Defias Brotherhood made a resurgence under the leadership of Vanessa VanCleef, daughter and successor of Edwin, who attempted to rally the discontented masses in Moonbrook to overthrow the power in Stormwind City. While they managed to burn Sentinel Hill to the ground, they were once again defeated by the adventurers and the forces of the Stormwind Army.\n\nIn the years that followed, the kingdom continued to support the region, waging a war against banditry and the Riverpaw gnolls. Following his coronation, King Anduin Wrynn's reforms brought more aid to the region, which extinguished the spark of the revolution. He also gave the royal pardon and reparations to the former Stonemasons and their families hidden in the region, allowing them to end their life of banditry and return to Stormwind City. The Breadbasket Guild was later formed by the farmers to revitalize the region with the support of the House of Nobles.",
		source = "https://warcraft.wiki.gg/wiki/Westfall",
	},
	[1437] = {
		name = "Wetlands",
		short = "The Wetlands is a large, wet region below Stonewrought Dam and north of Loch Modan, covered with small rivers, lakes, and ponds. Bordered on three sides by mountains, the Wetlands are open to the Great Sea to the west.",
		full = "The Wetlands is a large, wet region below Stonewrought Dam and north of Loch Modan, covered with small rivers, lakes, and ponds. Bordered on three sides by mountains, the Wetlands are open to the Great Sea to the west. Adventurers seeking a route to the Wetlands must either come through sieged Dun Algaz from Loch Modan or cross the damaged Thandol Span from the Arathi Highlands.\n\nThe Wetlands is a vast, cold swamp. Mists cloak the ground, and the overcast sky makes the land a uniform gray. Many Ironforge strongholds once stood in this region, but war has reduced them to rubble. Wild creatures, murlocs and orcs of Dragonmaw clan now control the land. The night elves also maintain a small holdout in the eastern parts, the Greenwarden's Grove - home to the fabled Rethiel the Greenwarden.",
		source = "https://warcraft.wiki.gg/wiki/Wetlands",
	},
	[1438] = {
		name = "Teldrassil",
		short = "Teldrassil (meaning \"Crown of the Earth\" in Darnassian) was a World Tree situated on the eponymous island off Kalimdor's northwestern coast.",
		full = "Teldrassil (meaning \"Crown of the Earth\" in Darnassian) was a World Tree situated on the eponymous island off Kalimdor's northwestern coast. Created shortly after the Third War by the night elves, Teldrassil served as their home and primary base of operations, its thick crown housing the capital city of Darnassus. Other major settlements on the tree included Rut'theran Village, Dolanaar and Shadowglen. Owing to its size, Teldrassil possessed its own unique ecosystem with a variety of flora, fauna, and vast twilit forests.\n\nAccording to Broll Bearmantle, as a World Tree, Teldrassil was linked to the very health of Azeroth, affecting not merely its immediate surroudings, but those lands beyond the island, and a Teldrassil that was not well could not properly maintain the balance between nature and decay. The new tree was not blessed by the Dragon Aspects at its birth, unlike its predecessor Nordrassil, which would ultimately leave it vulnerable to corruption from the Emerald Nightmare.\n\nTeldrassil served as the largest bastion of Alliance power in Kalimdor, and maintained naval connections to the mainland, the nearby Azuremyst Isles, and the distant Eastern Kingdoms. Many young and ambitious night elves began their journey out into the world from the verdant shelter of the World Tree. During the War of the Thorns -- roughly a decade after its creation -- Teldrassil was burned down by the Horde under the orders of Warchief Sylvanas Windrunner, killing many of the night elves dwelling in it.",
		source = "https://warcraft.wiki.gg/wiki/Teldrassil",
	},
	[1439] = {
		name = "Darkshore",
		short = "Darkshore is a long strip of coast on the northwestern part of Kalimdor. It is known for its characteristically shadowed woods and rocky beaches, littered with ancient ruins and mountainside caves.",
		full = "Darkshore is a long strip of coast on the northwestern part of Kalimdor. It is known for its characteristically shadowed woods and rocky beaches, littered with ancient ruins and mountainside caves. It was the only Alliance zone on the mainland of Kalimdor, with the village of Lor'danel serving as a friendly trading post, before it became contested during the War of the Thorns. Old night elf ruins stand crumbling on the cliffs, infested with naga, satyrs, grell, and haunting ghosts. Even the seas are unsafe, as bloodthirsty frenzies, gigantic threshadons, and hostile murlocs lurk beneath the waves.\n\nUnder Maiev Shadowsong's leadership, and with the assistance of the kingdom of Gilneas, the kaldorei ultimately won the Battle for Darkshore. Following the armistice, they eventually abandoned Bashal'Aran, allowing the settlement to return to ruins, while Tyrande Whisperwind and her Sentinels began largely focusing their wrath against the Horde elsewhere.",
		source = "https://warcraft.wiki.gg/wiki/Darkshore",
	},
	[1440] = {
		name = "Ashenvale",
		short = "Ashenvale, also known as Ashenvale Forest, is a wilderness region south of Darkshore and Felwood, west of Azshara, and north of the Stonetalon Mountains and the Barrens.",
		full = "Ashenvale, also known as Ashenvale Forest, is a wilderness region south of Darkshore and Felwood, west of Azshara, and north of the Stonetalon Mountains and the Barrens. It is the ancestral homeland of the night elves, under the protection of their Sentinels and the children of the demigod Cenarius, with Astranaar as their main settlement. Since the Third War, the Horde has expanded their influence in the eastern part of the woods, with Splintertree Post as their main base of operations. The region is heavily populated with furbolgs, satyr, and wild creatures such as spiders, wolves, and bears.",
		source = "https://warcraft.wiki.gg/wiki/Ashenvale",
	},
	[1441] = {
		name = "Thousand Needles",
		short = "Thousand Needles is a huge flooded canyon in southern Kalimdor, filled with towering mesas. In the east, the canyon opens up to what was once the Shimmering Flats, where Fizzle & Pozzik's Speedbarge is located.",
		full = "Thousand Needles is a huge flooded canyon in southern Kalimdor, filled with towering mesas. In the east, the canyon opens up to what was once the Shimmering Flats, where Fizzle & Pozzik's Speedbarge is located.\n\nMany residents, such as the centaur clans, have been wiped out entirely. The iconic Great Lift has been destroyed, while the Alliance outpost of Thalanaar on the Feralas border has been flooded and its residents moved to higher ground. Meanwhile, the Southsea Pirates have gained a foothold in Southsea Holdfast, and the Twilight's Hammer cult controls several areas formerly of little interest or inaccessible altogether. The Horde forces of Freewind Post and the new Westreach Summit are now in a struggle for survival.\n\nThe twisting rock tower needles were cut and sharpened over centuries by water.",
		source = "https://warcraft.wiki.gg/wiki/Thousand_Needles",
	},
	[1442] = {
		name = "Stonetalon Mountains",
		short = "The Stonetalon Mountains are a range of peaks that lie west of the Northern Barrens, south of Ashenvale, and north of Desolace.",
		full = "The Stonetalon Mountains are a range of peaks that lie west of the Northern Barrens, south of Ashenvale, and north of Desolace. The mountains are traditionally the ancestral home of the harpies, but their numbers have dwindled with the turmoil in the region. Stonetalon Peak, the largest mountain in the range, has long been a sacred place for both the night elves and tauren. The night elves once maintained a barrow and a glade at the top, but the area has since come under attack by a sinister force. The mountains further south are less forested, although some sparse evergreens grow in certain spots, particularly the Greatwood Vale. Windshear Crag has been decimated by years of logging by various factions, leaving the air is filled with soot and spoiling the area's water with oil and waste. The night elves have several holds, while the tauren have a settlement in the centrally located Sun Rock Retreat and the Darkspear trolls have a village further south at Malaka'jin. The Horde and Alliance also have posts at various battlefronts throughout the mountains. The mountains are home to creatures such as kobolds, spiders, and eagles, while the Charred Vale stretches out to the sea and holds several especially dangerous black dragons and elementals.",
		source = "https://warcraft.wiki.gg/wiki/Stonetalon_Mountains",
	},
	[1443] = {
		name = "Desolace",
		short = "Desolace, originally known as Mashan'she, is a large, arid region on the western coast of Kalimdor, nestled between the Stonetalon Mountains in the north and the jungles of Feralas in the south.",
		full = "Desolace, originally known as Mashan'she, is a large, arid region on the western coast of Kalimdor, nestled between the Stonetalon Mountains in the north and the jungles of Feralas in the south. The homeland of the barbarous centaur, Desolace was once nothing but a massive grey desert, filled with dead trees and skulls of dead kodo, along with warring centaur tribes and the malevolent, demon-worshipping Burning Blade clan.\n\nDespite this, conflict continues to rage between various factions, including the Horde and Alliance. The Magram, Kolkar and Gelkis tribes of centaur continue to fight, whilst the demonic Burning Legion gathers in Mannoroc Coven. With the Burning Blade to the north in Thunder Axe Fortress, satyrs in the northeastern ruins, and naga on the northwest coast, Desolace remains a harsh environment even with the Cenarion Circle's best efforts. The sacred Centaur grounds of Maraudon are the only instance in the area.",
		source = "https://warcraft.wiki.gg/wiki/Desolace",
	},
	[1444] = {
		name = "Feralas",
		short = "Feralas, unlike its barren neighbors to the north, south, and east, is a lush jungle. Both the Horde and Alliance lay claim to the area and have to contend with powerful local forces.",
		full = "Feralas, unlike its barren neighbors to the north, south, and east, is a lush jungle. Both the Horde and Alliance lay claim to the area and have to contend with powerful local forces. These include the bloodthirsty Gordunni ogres who control a number of scattered ancient elven ruins, including the vast ruined city now known as Dire Maul. The ogres have desecrated and defiled much of Feralas, damaging the land with their taint. The Horde in particular is concerned with the unchecked expansion of the Gordunni and has put out a call for adventurers to aid the war effort against them. Feralas is also home to a number of Woodpaw gnolls and Grimtotem tauren, members of which are hunted by order of Belgrom Rockmaul in Orgrimmar. The far western islands are crawling with naga and recently several silithid hives have been spotted. Feralas is also the location of one of the four Great Trees leading to the Emerald Dream.",
		source = "https://warcraft.wiki.gg/wiki/Feralas",
	},
	[1445] = {
		name = "Dustwallow Marsh",
		short = "Dustwallow Marsh (or Dustwallow Swamp) is a vast and ancient swamp in the eastern reaches of Central Kalimdor.",
		full = "Dustwallow Marsh (or Dustwallow Swamp) is a vast and ancient swamp in the eastern reaches of Central Kalimdor. Although there is little activity in the area, the Alliance and the Horde have recently expanded their influence in the region. The Horde major stronghold in the area is Brackenwall Village, the new home of the ogre Stonemaul clan.\n\nIn earlier years, scattered reports of black whelps spotted in the southern region sent hunters rushing to claim Stormwind's bounty. Few ever succeeded in locating one of Onyxia's lost brood. Now, few who enter this marsh wish to be found, let alone trifled with. There are many scattered refugees of the Second War who are unable to find hearth or kin in a kinder climate. Though roadways connect dry stretches of land to coastal vistas, few beyond the occasional fisherman have risked such paths since the destruction of Theramore.",
		source = "https://warcraft.wiki.gg/wiki/Dustwallow_Marsh",
	},
	[1446] = {
		name = "Tanaris",
		short = "Tanaris, or the Tanaris Desert, is a desert located in Southern Kalimdor, east of Un'Goro Crater and south of Thousand Needles. It is an arid land, covered in sand dunes and frequently exposed to dangerous sandstorms.",
		full = "Tanaris, or the Tanaris Desert, is a desert located in Southern Kalimdor, east of Un'Goro Crater and south of Thousand Needles. It is an arid land, covered in sand dunes and frequently exposed to dangerous sandstorms. The Steamwheedle Cartel goblins have established Steamwheedle Port and Gadgetzan as their main centers of operation.",
		source = "https://warcraft.wiki.gg/wiki/Tanaris",
	},
	[1447] = {
		name = "Azshara",
		short = "Azshara is a beautiful coastal area cloaked in eternal autumn. It is located in northeastern Kalimdor, east of Ashenvale, south of Winterspring, and north of Durotar.",
		full = "Azshara is a beautiful coastal area cloaked in eternal autumn. It is located in northeastern Kalimdor, east of Ashenvale, south of Winterspring, and north of Durotar. The trees and other flora are tinged in brilliant oranges and reds, and nearer the coast, great cliffs and sandy beaches line the ocean. The region's hostile inhabitants include enraged ghosts, vicious satyr, stalking naga, and ferocious wildlife.",
		source = "https://warcraft.wiki.gg/wiki/Azshara",
	},
	[1448] = {
		name = "Felwood",
		short = "Felwood is a corrupted forest filled with tainted creatures of the woods, demonic satyr and infernals, and rotting treants and ancients.",
		full = "Felwood is a corrupted forest filled with tainted creatures of the woods, demonic satyr and infernals, and rotting treants and ancients. It is located in Northern Kalimdor, north of Ashenvale, east of Darkshore, and west of Mount Hyjal and Winterspring.\n\nOnce a serene forest and a part of northern Ashenvale, it was corrupted by the dreadlord Tichondrius and the Skull of Gul'dan during the Third War, and its healing has been very slow over the recent years. The Emerald Circle, a sub-section of the Cenarion Circle druids, have been working to heal the land and defeat the remaining demons that corrupt it, specifically the remaining Shadow Council forces led by Lord Banehollow. It is also home to one of the two tribes of pure furbolgs left in the world -- the Timbermaw tribe. There are no dungeons or battlegrounds of any kind in this area.",
		source = "https://warcraft.wiki.gg/wiki/Felwood",
	},
	[1449] = {
		name = "Un'Goro Crater",
		short = "Un'Goro Crater, sometimes stylized as Un'goro Crater, and meaning \"God Lands\" in the Qiraji language, lies at the central part of Southern Kalimdor, between Tanaris, Silithus and Uldum.",
		full = "Un'Goro Crater, sometimes stylized as Un'goro Crater, and meaning \"God Lands\" in the Qiraji language, lies at the central part of Southern Kalimdor, between Tanaris, Silithus and Uldum. Although the area is almost completely isolated from the rest of the world and sandwiched between three deserts, the crater is filled with exotic plant life and even more exotic creatures. Ranging from peaceful earth elementals to raging devilsaurs, the locals are not to be trifled with. The zone annually hosts the Un'Goro Madness micro-event.",
		source = "https://warcraft.wiki.gg/wiki/Un'Goro_Crater",
	},
	[1450] = {
		name = "Moonglade",
		short = "The Moonglade (also spelled Moonglades and Moon Glade) is a vale in Northern Kalimdor that serves as a haven for druids, and is also the home of the Cenarion Circle.",
		full = "The Moonglade (also spelled Moonglades and Moon Glade) is a vale in Northern Kalimdor that serves as a haven for druids, and is also the home of the Cenarion Circle. Moonglade's reflection within the Emerald Dream is the most sacred place in the entire realm. Here, tauren and night elves coexist peacefully, united by their reverence for the spirit of nature. Conflict between the races in Moonglade is not tolerated by the Moonglade Wardens stationed throughout the main town of Nighthaven, who will respond to any violence initiated against individuals with a favorable reputation with the Circle.\n\nThe demigod Omen sleeps at the depths of the central lake, awakening every year around the time of the Lunar Festival, after which he is routinely put to rest. The Lunar Festival itself is based in Nighthaven and the Moonkin Festival also occurs in the area. In a corrupted version version of the Moonglade located within the Emerald Nightmare, an entrance to the Rift of Aln can be found.",
		source = "https://warcraft.wiki.gg/wiki/Moonglade",
	},
	[1451] = {
		name = "Silithus",
		short = "Silithus (also known as the Silithus Desert) forms the southwestern corner of Kalimdor.",
		full = "Silithus (also known as the Silithus Desert) forms the southwestern corner of Kalimdor. It can only be reached on foot by traveling to the northwestern corner of Un'Goro Crater, where a wide path extends out of the crater and into Silithus.\n\nSilithus is one of the insect infested sections of southern Kalimdor. This area houses a section of the once great Aqiri empire, known as Ahn'Qiraj. It is currently uninhabited, but the central temple is sealed off by the night elves, who attempted to prevent an infestation from breaking out. They were unsuccessful in their attempt to seal them behind the Scarab Wall and over the millennia the Silithid spread hives from Silithus to as far as Feralas. The Cenarion Circle maintains a constant presence in Silithus at Cenarion Hold. From here they monitor the defeated Silithid hives, whom the Cenarion Circle suppressed alongside the Alliance and Horde during the opening of the gates of Ahn'Qiraj. The bronze dragonflight, Nozdormu's brood, returned to the desert for the first time in ten thousand years before the opening of the gates.\n\nSilithus had been fleshed out as a major quest hub with episodic storylines that extend into its depths and past its borders during the Gates of Ahn'Qiraj event. The redesign of this zone included a high-end outdoor quest area for solo players, while 5-man groups could tackle outdoor raid bosses.\n\nA new crystalline substance called \" [Silithyst]\" has been discovered, and both the Horde and Alliance have taken an interest in it. Players collect the dust where they can but must be careful they are not ambushed by opposing faction members before they can make their drop-off. See The Silithyst Must Flow for details.\n\nConsidering the vast majority of quests in the region involving the Silithid and Qiraji being removed and the focus now being on battling the increased presence of the Twilight's Hammer cult, it can be assumed that the threat of C'Thun and his retinue is gone, if only for a moment.\n\nAt the end of the third invasion of the Burning Legion Silithus was completely devastated when Sargeras tried to destroy Azeroth after impaling his sword of into the center of the desert.",
		source = "https://warcraft.wiki.gg/wiki/Silithus",
	},
	[1452] = {
		name = "Winterspring",
		short = "Winterspring (also known as Winterspring Valley) is a snowy valley located in Northern Kalimdor, east of Felwood, northeast of Mount Hyjal, and north of Azshara.",
		full = "Winterspring (also known as Winterspring Valley) is a snowy valley located in Northern Kalimdor, east of Felwood, northeast of Mount Hyjal, and north of Azshara. It holds the goblin trading post of Everlook, old night elf ruins, and the vast cave Mazthoril, the primary home of the blue dragonflight on Kalimdor. Many wild creatures roam this beautiful landscape.",
		source = "https://warcraft.wiki.gg/wiki/Winterspring",
	},
	[1453] = {
		name = "Stormwind City",
		short = "Stormwind City, also known as New Stormwind or simply Stormwind, is the capital city of the eponymous kingdom of Stormwind and the largest human city on Azeroth.",
		full = "Stormwind City, also known as New Stormwind or simply Stormwind, is the capital city of the eponymous kingdom of Stormwind and the largest human city on Azeroth. Located north of Elwynn Forest on Azeroth region's northwest coast, it has become one of the last great human cities after the Third War, and embodies the heart of the Alliance. Stormwind's willingness to work with others to find diplomatic solutions stands out as one of its true strengths. Its citizens hold fast to the principles of honor and justice as they defend their settlements and the Alliance against any aggressors.\n\nNo city better demonstrates human determination than Stormwind. Destroyed by the Orcish Horde during the First War, the capital was painstakingly reconstructed by the Stonemasons' Guild after the Second War. From the magnificent Cathedral of Light, which serves as a major spiritual hub, to the awe-inspiring Valley of Heroes, which commemorates the sacrifices of Stormwind's loyal champions, the city truly represents the courageous heart of humanity, and serves as a bastion of the Holy Light.\n\nThe Stormwind City Guard are the law enforcement and protectors of Stormwind City, keeping the peace within the city's walls.",
		source = "https://warcraft.wiki.gg/wiki/Stormwind_City",
	},
	[1454] = {
		name = "Orgrimmar",
		short = "Orgrimmar ['ɔɹgɹɪmɑɹ] is the capital city of the orcs and the Horde as a whole.",
		full = "Orgrimmar ['ɔɹgɹɪmɑɹ] is the capital city of the orcs and the Horde as a whole. Named in honor of the legendary Orgrim Doomhammer, and nestled into a system of valleys on the northern edge of Durotar, Orgrimmar stands as one of the mightiest warrior cities in the world. It is the seat of the Horde Council that governs the entire faction. It is the primary hub for player characters of the Horde and, as with all capital cities, has banks, class and profession trainers, and auction houses.",
		source = "https://warcraft.wiki.gg/wiki/Orgrimmar",
	},
	[1455] = {
		name = "Ironforge",
		short = "Ironforge (displayed as the City of Ironforge in the overworld) is the capital city of the dwarves, proud members of the Alliance.",
		full = "Ironforge (displayed as the City of Ironforge in the overworld) is the capital city of the dwarves, proud members of the Alliance. Carved into the depths of Ironforge Mountain in northern Dun Morogh, it is the ancestral home of the dwarves and one of the oldest cities on Azeroth. The Council of Three Hammers rules over the city to ensure the fair and equal treatment of all dwarves within its walls from the High Seat. The city is also the capital of the Kingdom of Khaz Modan, which is ruled by the Bronzebeard clan.\n\nAn expansive underground city of craftsmen, explorers, miners, and warriors, famous for its industry and as an Alliance center of commerce, Ironforge is equal parts fortress and capital and a testament to the dwarves' strength and resilience. The city consists of a series of concentric rings, with the smaller levels deeper underground, all radiating out from the namesake Great Forge at its center. Ironforge is perhaps the most intricate of the Alliance cities, boasting many small passageways, shops built into the rock walls, and cavernous rooms. The feel of the city is a bustling, rowdy, and somewhat industrial one, where there are always a thousand things happening at any time of the day or night. However, it is predominantly safe-feeling and cozy; fires roar in the hearths of the inns and shops, and much dwarven laughing and frivolity is to be heard. Also, unlike Stormwind and Darnassus, the city is actually a massive cavern carved into the earth by the dwarves; the ceiling and floor are both hard stone.\n\nMainly because of the Deeprun Tram, linking Ironforge and Stormwind City, and the district of Tinker Town, Ironforge is one of the most racially diverse cities in the Alliance world. With the Council of Three Hammers uniting all three dwarven clans, Ironforge has recently welcomed Dark Iron dwarves and Wildhammer dwarves into Ironforge as well.\n\nThe collective frivolity, the bustling and gruff manner of the dwarves, and the proximity to many quest and raid areas have historically made Ironforge, along with Stormwind City, a popular place to idle.",
		source = "https://warcraft.wiki.gg/wiki/Ironforge",
	},
	[1456] = {
		name = "Thunder Bluff",
		short = "Thunder Bluff (sometimes spelled as Thunderbluff) is the tauren capital city located in the northern part of the region of Mulgore on the continent of Kalimdor.",
		full = "Thunder Bluff (sometimes spelled as Thunderbluff) is the tauren capital city located in the northern part of the region of Mulgore on the continent of Kalimdor. The entire city is built on bluffs several hundred feet above the surrounding landscape and is accessible by elevators on the southwestern and northeastern sides. Established by the wise chieftain Cairne Bloodhoof and his stalwart tribe, Thunder Bluff overlooks the verdant land of Mulgore from atop a series of windswept mesas. Prior to the construction of the capital, the tauren had lived as nomads for countless generations, often under attack by marauding bands of centaur. With Thunder Bluff's founding, however, the proud and good-spirited race was finally granted a permanent home.\n\nThe city of many tribes is a hub for tauren, welcoming tradesfolk and artisans of every kind.",
		source = "https://warcraft.wiki.gg/wiki/Thunder_Bluff",
	},
	[1457] = {
		name = "Darnassus",
		short = "Darnassus (aka Darnassus City), now known as Remains of Darnassus, was the capital city of the night elves of the Alliance, found in western Teldrassil.",
		full = "Darnassus (aka Darnassus City), now known as Remains of Darnassus, was the capital city of the night elves of the Alliance, found in western Teldrassil. The High Priestess, Tyrande Whisperwind, resided in the Temple of the Moon, surrounded by other sisters of Elune and her mate, the Archdruid Malfurion Stormrage.\n\nDarnassus was the greatest city of the night elves, housing the leaders of both the druids and the faithful of Elune. It was carefully guarded by Sentinels, ancient protectors, and ancients of war. It was destroyed during the Burning of Teldrassil.",
		source = "https://warcraft.wiki.gg/wiki/Darnassus",
	},
	[1458] = {
		name = "Undercity",
		short = "The Undercity, now known as the Ruins of Undercity, was the capital city of the Forsaken kingdom, located beneath the ruins of Capital City in Tirisfal Glades.",
		full = "The Undercity, now known as the Ruins of Undercity, was the capital city of the Forsaken kingdom, located beneath the ruins of Capital City in Tirisfal Glades. Originally intended by Arthas Menethil to be the Scourge's seat of power in Lordaeron, the budding \"Undercity\" was abandoned when the death knight was recalled by the Lich King in the distant Northrend. During the Plaguelands civil war, Sylvanas Windrunner and the Forsaken rebels claimed the Undercity for their own, then spent years completing the twisted maze of catacombs the Scourge had begun constructing. It was much more defensible than the city above it.\n\nPlagued by the Banshee Queen during the Battle for Lordaeron, its surface has since been cleansed by the efforts of the Desolate Council.",
		source = "https://warcraft.wiki.gg/wiki/Undercity",
	},
}
